use crate::ciphers::pearson::cipher::pearson_digest;
use crate::ciphers::pearson::keys::pearson_default_key;
use crate::core::sample::sample_bytes;
use crate::core::timer::Stopwatch;

/// Time one digest pass over `input_len` generated bytes.
pub fn pearson_measure(input_len: usize) -> u128 {
    let data = sample_bytes(input_len);
    let seed = pearson_default_key();
    let watch = Stopwatch::start();
    let out = pearson_digest(&data, seed);
    std::hint::black_box(out);
    watch.elapsed_ns()
}
